11	export async function POST(request: NextRequest) {
12	  const authUser = await getAuthenticatedUser()
13	  if (!authUser) {
14	    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
15	  }
16	
17	  const { success } = await authedRatelimit.limit(authUser.user.id)
18	  if (!success) {
19	    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
20	  }
21	
22	  let formData: FormData
23	  try {
24	    formData = await request.formData()
25	  } catch {
26	    return NextResponse.json({ error: 'Invalid form data' }, { status: 400 })
27	  }
28	
29	  const file = formData.get('file')
30	  if (!(file instanceof File)) {
31	    return NextResponse.json({ error: 'No file provided' }, { status: 400 })
32	  }
33	
34	  if (!ALLOWED_MIME_TYPES.includes(file.type)) {
35	    return NextResponse.json(
36	      { error: `File type not allowed. Use: ${ALLOWED_MIME_TYPES.join(', ')}` },
37	      { status: 400 }
38	    )
39	  }
40	
41	  if (file.size > MAX_BYTES) {
42	    return NextResponse.json(
43	      { error: `File must be under 10 MB. Yours is ${(file.size / 1024 / 1024).toFixed(1)} MB.` },
44	      { status: 400 }
45	    )
46	  }
47	
48	  try {
49	    const supabase = await createClient()
50	    const ext = file.type.split('/')[1]
51	    const path = `${authUser.studioId}/cover.${ext}`
52	
53	    const { error: uploadError } = await supabase.storage
54	      .from('studio-assets')
55	      .upload(path, file, {
56	        contentType: file.type,
57	        upsert: true,
58	      })
59	
60	    if (uploadError) {
61	      logger.error({ err: uploadError, studioId: authUser.studioId }, 'cover image upload failed')
62	      return NextResponse.json({ error: 'Upload failed' }, { status: 500 })
63	    }
64	
65	    const { data: urlData } = supabase.storage.from('studio-assets').getPublicUrl(path)
66	
67	    return NextResponse.json({ url: urlData.publicUrl })
68	  } catch (err) {
69	    logger.error({ err, studioId: authUser.studioId }, 'cover image upload unexpected error')
70	    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
